import { AcademyAIHub } from './AcademyAIHub';
import { BookOpen, CheckCircle2, ChevronRight, Clock3, GraduationCap, PlayCircle, Search, ShieldCheck, Video } from 'lucide-react';

type Lesson = {
  id: string; title: string; category: string; level: string; duration: string; summary: string;
  objective: string; steps: string[]; narration: string; visualPrompt: string;
  quiz: { question: string; answers: string[]; correct: number; explanation: string };
};

const LESSONS: Lesson[] = [
  { id: 'welcome', title: 'Welcome to SuperTechAi', category: 'Getting started', level: 'Beginner', duration: '3 min', summary: 'Understand what the platform does and where to begin.', objective: 'Know where to find the tools you need and what the platform can and cannot do.', steps: ['Open your Dashboard for the market overview and monitored assets.', 'Use the navigation bar to explore signals, crypto, orders, network and earnings.', 'Visit Academy whenever you need a guided explanation.', 'Remember that signals support decisions; they do not guarantee outcomes.'], narration: 'Welcome to SuperTechAi. Your platform brings market intelligence, trading signals, crypto monitoring, automation tools and member services into one place. Start with the Dashboard, explore each section at your own pace, and use the Academy whenever you need help. SuperTechAi helps you make more informed decisions. It does not remove market risk or guarantee profits.', visualPrompt: 'Show a premium dark navy fintech dashboard, cyan and subtle gold accents, a friendly professional narrator, readable captions and smooth UI transitions. Introduce market intelligence, signals, crypto monitoring, automation and member tools. End with: Learn the platform. Understand the risk. Make informed decisions.', quiz: { question: 'What is SuperTechAi designed to provide?', answers: ['Guaranteed profits', 'Trading intelligence and platform tools', 'A replacement for risk management'], correct: 1, explanation: 'SuperTechAi provides information and tools. Trading outcomes are never guaranteed.' } },
  { id: 'dashboard', title: 'Your Dashboard explained', category: 'Trading intelligence', level: 'Beginner', duration: '4 min', summary: 'Read the market overview, asset selector, live status and signal cards.', objective: 'Find key information without getting lost in technical details.', steps: ['Check the connection and market status at the top.', 'Choose the assets you want SuperTechAi to monitor.', 'Review signal direction, entry information and current status.', 'Open the chart snapshot to understand recent price movement.'], narration: 'The Dashboard is your starting point. First, check that market data is connected. Next, choose the assets you want to follow. Each signal card presents the current direction and important trade information. Open the chart snapshot to inspect recent price movement. A signal is a prompt to review the market, not an instruction to trade blindly.', visualPrompt: 'Create a screen-led tutorial using a fictional dark trading dashboard. Animate the status bar, asset selector, signal cards and chart snapshot. Use cursor highlights, cyan outlines and short captions. Do not invent live prices or performance claims.', quiz: { question: 'What should you check before relying on a signal?', answers: ['Connection status and chart context', 'Only the signal colour', 'Nothing else'], correct: 0, explanation: 'Check that data is connected and review chart context and risk.' } },
  { id: 'signals', title: 'Understanding Trading Signals', category: 'Trading intelligence', level: 'Beginner', duration: '5 min', summary: 'Learn BUY and SELL signals, confirmation and trade levels.', objective: 'Understand what a signal communicates before deciding whether it fits your plan.', steps: ['BUY indicates conditions may favour an upward move.', 'SELL indicates conditions may favour a downward move.', 'Review timeframe, entry, stop loss and take-profit information.', 'Wait for confirmation and use your own risk controls.'], narration: 'A BUY signal means the system has detected conditions that may favour an upward move. A SELL signal means conditions may favour a downward move. Neither is a promise. Before taking action, review the timeframe, entry area, stop loss and targets. Respect confirmation rules and never risk money you cannot afford to lose.', visualPrompt: 'Show simple animated BUY and SELL cards, candle-close confirmation, entry, stop-loss and take-profit markers. Keep language beginner-friendly. Show both winning and losing example paths so viewers understand uncertainty.', quiz: { question: 'Does a BUY or SELL signal guarantee the expected price move?', answers: ['Yes', 'No, it is a probability-based signal'], correct: 1, explanation: 'Signals can fail. Use risk controls and make your own informed decision.' } },
  { id: 'super', title: 'How Super Signal works', category: 'Trading intelligence', level: 'Intermediate', duration: '4 min', summary: 'Understand why agreement across all eight timeframes matters.', objective: 'Recognise a high-confluence alert and why confirmation still matters.', steps: ['Super Signal looks for agreement across eight timeframes.', 'The alert appears when all required timeframes align.', 'Review reversal context and the underlying chart before acting.', 'If conditions change, wait for a fresh setup instead of chasing price.'], narration: 'Super Signal highlights moments when all eight monitored timeframes point in the same direction. This agreement can provide stronger context than a single timeframe alone. It does not guarantee a successful trade. Check the chart, understand the broader move, and apply your risk plan.', visualPrompt: 'Animate eight timeframe tiles aligning, then show a Super Signal alert and a clean candlestick chart with higher-timeframe context and a risk checklist. Do not imply certainty or guaranteed win rates.', quiz: { question: 'What makes a Super Signal different?', answers: ['It uses one timeframe only', 'It requires agreement across eight timeframes', 'It removes trading risk'], correct: 1, explanation: 'The defining feature is agreement across all eight monitored timeframes.' } },
  { id: 'crypto', title: 'Crypto Watchlist and market movers', category: 'Crypto', level: 'Beginner', duration: '4 min', summary: 'Explore Binance assets, top gainers, losers and alerts.', objective: 'Find crypto opportunities without confusing market movement with a confirmed setup.', steps: ['Open Crypto to view monitored assets and market movers.', 'Use gainers and losers as a discovery list, not an automatic trade list.', 'Open an asset to review its chart and available analysis.', 'Add assets to your monitored list when you want them on your Dashboard.'], narration: 'The Crypto section helps you discover what is moving. Top gainers and losers show movement, not a guaranteed opportunity. Open an asset to inspect its chart and analysis. Add symbols you want to monitor, then review any signal and your risk settings before considering a trade.', visualPrompt: 'Show a dark watchlist, green and red market mover rows, asset detail charts and the distinction between price movement and a confirmed signal. Use fictional sample data and never claim future returns.', quiz: { question: 'Does appearing among top gainers automatically mean an asset is a BUY?', answers: ['Yes', 'No, review its analysis and risk first'], correct: 1, explanation: 'A price mover is a discovery cue, not a trade recommendation by itself.' } },
  { id: 'automation', title: 'Trading automation and pending orders', category: 'Automation', level: 'Advanced', duration: '6 min', summary: 'Understand connected accounts, automation controls and order monitoring.', objective: 'Know the difference between an analysis signal and an executed order.', steps: ['Read connection and account status before enabling automation.', 'Review configured assets, order rules and risk limits.', 'Use Pending Orders to inspect queued opportunities and their status.', 'Monitor execution and account exposure; pause automation if anything looks wrong.'], narration: 'Automation can help carry out a defined plan, but it makes configuration and monitoring more important. A signal is analysis. A pending order is an instruction waiting for its conditions. An executed order is a live position. Check your connection, allowed assets, risk limits and order details before enabling automation. Monitor activity regularly.', visualPrompt: 'Explain a trading automation control panel, connection status, allowed assets, risk limit, pending order queue and execution status. Show a pre-flight checklist and pause control. Never imply risk-free automation.', quiz: { question: 'What is the difference between a pending order and an executed order?', answers: ['They are identical', 'A pending order is waiting for conditions; executed means a trade opened', 'A pending order is a completed profit'], correct: 1, explanation: 'A pending order has not necessarily opened a position yet.' } },
  { id: 'network', title: 'Referrals and your network', category: 'Membership', level: 'Beginner', duration: '5 min', summary: 'Find your referral link and understand how your network grows.', objective: 'Share your invitation correctly and distinguish real members from open positions.', steps: ['Open My Referrals to find your personal referral link.', 'Share the link with someone who wants to join.', 'After payment confirmation, the member becomes active.', 'Open Network to explore the structure and available positions.'], narration: 'Your referral link helps new members register under your invitation. Share the correct link and let the person complete membership payment. Once payment is confirmed, the member becomes active and appears in the network. Open positions are spaces for future members; they are not people or confirmed sales.', visualPrompt: 'Show a referral link journey: share link, registration, payment confirmation, active member and network tree updating. Distinguish empty positions from actual members. Do not promise earnings.', quiz: { question: 'When should a new member appear as an active paid member?', answers: ['As soon as the link is shared', 'After membership payment is confirmed', 'When they view the network page'], correct: 1, explanation: 'Sharing a link is not a sale. Payment must be confirmed.' } },
  { id: 'wallet', title: 'Earnings, wallet and withdrawals', category: 'Membership', level: 'Intermediate', duration: '5 min', summary: 'Understand balances, your TRC20 wallet and withdrawal procedures.', objective: 'Know where earnings are shown and how to keep payout details accurate.', steps: ['Open My Earnings to review balances and transaction history.', 'Save the correct USDT TRC20 payout address in wallet settings.', 'Review any withdrawal fee and net payout before submitting.', 'Check withdrawal status and transaction reference after processing.'], narration: 'Your Earnings area shows balances recorded for your member account. Keep your USDT TRC20 payout wallet accurate and secure. Before submitting a withdrawal, review the amount, fee and net payout. A submitted request does not always mean the blockchain transfer is complete. Check the final status and transaction reference.', visualPrompt: 'Show a sample earnings ledger, masked example TRC20 address, withdrawal amount, fee and net payout confirmation. Never display real wallet credentials, private keys or member data. Explain that a submitted request and a confirmed blockchain transfer are different states.', quiz: { question: 'Should you share your wallet private key to receive a payout?', answers: ['Yes', 'No, only provide the public TRC20 receiving address'], correct: 1, explanation: 'Never share a private key or recovery phrase. A receiving address is public.' } },

  { id: 'market-basics', title: 'Trading from zero: what a market is', category: 'Trading foundations', level: 'Beginner', duration: '8 min', summary: 'Understand buyers, sellers, price movement, and why markets move.', objective: 'Explain trading in everyday language and understand that every trade has uncertainty.', steps: ['A market is where buyers and sellers exchange an asset. The price changes as their willingness to buy and sell changes.', 'A BUY trade aims to benefit if the price rises after entry. A SELL trade aims to benefit if the price falls after entry. You can lose money in either direction.', 'Learn the difference between investing (often holding for a longer period) and trading (seeking to benefit from shorter price movements).', 'Know what you are trading: a currency pair, cryptocurrency, stock, index or another instrument. Each has different trading hours, costs and risks.', 'Before placing a trade, identify your reason for entering, the price that proves your idea wrong, and the amount you can afford to lose.'], narration: 'Trading is the act of buying or selling a financial instrument with the aim of benefiting from a change in its price. Imagine a marketplace. When more people are willing to buy at higher prices, price may rise. When sellers are more eager, price may fall. Nobody knows the next move with certainty. Your job is not to predict every candle. Your job is to make a plan, control risk and learn from the result.', visualPrompt: 'A beginner-friendly animated marketplace analogy transitioning into a simple price chart. Label buyers, sellers, rising price and falling price. Use everyday words and clear captions.', quiz: { question: 'What does a trading plan need to include?', answers: ['Only a direction', 'A reason to enter, an exit plan and a defined risk', 'A promise that price will move'], correct: 1, explanation: 'A plan defines why you enter, when you exit and how much you risk.' } },
  { id: 'market-types', title: 'Forex, crypto, stocks and indices', category: 'Trading foundations', level: 'Beginner', duration: '8 min', summary: 'Compare the main markets and understand what makes each one different.', objective: 'Choose a market only after understanding its behaviour, costs and trading hours.', steps: ['Forex involves exchanging one currency against another. A pair such as EUR/USD compares the euro with the US dollar.', 'Cryptocurrencies are digital assets. They can trade around the clock, but prices may move sharply and liquidity differs between coins.', 'Shares represent ownership in a company. Their prices can respond to company results, industry changes and wider economic conditions.', 'Indices track a group of shares and provide a broad view of a market, rather than representing one company.', 'Check market hours, spreads, fees, liquidity, volatility and local rules before choosing an instrument.'], narration: 'There is no single market that is best for everyone. Forex compares currencies. Crypto assets can trade day and night and can be very volatile. Shares represent companies, while indices track groups of companies. Each market has different costs, opening hours and risks. Start by learning one market well instead of jumping between many instruments.', visualPrompt: 'Four clean illustrated panels: currency pair, digital coin, company share and market index. Show differences in trading hours and volatility without performance claims.', quiz: { question: 'Why should a beginner learn one market carefully first?', answers: ['Every market behaves identically', 'Different markets have different costs, hours and risks', 'It guarantees profit'], correct: 1, explanation: 'Market rules and behaviour differ, so learn the instrument you are trading.' } },
  { id: 'quotes-spread', title: 'Bid, ask, spread and trading costs', category: 'Trading foundations', level: 'Beginner', duration: '7 min', summary: 'Learn the real price you buy and sell at, and how costs affect results.', objective: 'Recognise trading costs before opening a position.', steps: ['The bid is generally the price at which you can sell; the ask is generally the price at which you can buy.', 'The difference between ask and bid is called the spread. It is one of the basic costs of entering a trade.', 'Some brokers also charge commissions, overnight financing or other fees. Crypto venues may charge maker or taker fees.', 'A wide spread can make a very short-term trade difficult because price must move enough to cover the cost.', 'Check the broker or exchange fee schedule and the live spread before entering. Costs can change with market conditions.'], narration: 'The price shown on a chart is not always the exact price at which your order will be filled. There is usually a buying price and a selling price. The gap between them is the spread. You may also pay commission or overnight fees. These costs matter, especially when you trade frequently or aim for small price moves. Always understand the full cost before you enter.', visualPrompt: 'Animate a simple bid and ask price board. Highlight the gap as spread, then show a small trade where costs matter. Avoid using real broker pricing.', quiz: { question: 'What is the spread?', answers: ['The difference between the buy and sell quote', 'A guaranteed profit', 'The number of candles on a chart'], correct: 0, explanation: 'The spread is the gap between the ask and bid prices.' } },
  { id: 'candles', title: 'Candlesticks made simple', category: 'Chart reading', level: 'Beginner', duration: '10 min', summary: 'Read candle open, close, high, low, body and wick.', objective: 'Understand what one candle tells you and what it cannot tell you.', steps: ['Every candle represents price movement during a chosen period, such as 5 minutes or 1 hour.', 'The candle body shows the open and close. The wicks show the highest and lowest prices reached during that period.', 'A rising candle usually closes above its open; a falling candle usually closes below its open. Chart colours can be customised, so read the legend.', 'A long body shows a larger move between open and close. Long wicks show that price travelled farther but did not hold that extreme.', 'Wait for the candle to close when your method depends on closing prices. An unfinished candle can change before it closes.'], narration: 'A candlestick is a small summary of what price did during a set period. The body shows where the candle opened and closed. The thin lines, called wicks, show the highest and lowest prices. A candle does not tell you what happens next. Read it together with the trend, important price areas and your trading plan.', visualPrompt: 'Build a large animated candlestick with labels for open, close, high, low, body and wick. Compare a rising candle, falling candle and long-wick candle.', quiz: { question: 'What do a candle’s wicks show?', answers: ['Only the opening price', 'The highest and lowest prices reached', 'The next candle direction'], correct: 1, explanation: 'Wicks show the high and low reached during that candle period.' } },
  { id: 'timeframes', title: 'Timeframes: from minutes to days', category: 'Chart reading', level: 'Beginner', duration: '8 min', summary: 'Understand M5, M15, H1, H4 and daily charts, and how they fit together.', objective: 'Use higher and lower timeframes without confusing short-term movement with the bigger picture.', steps: ['A timeframe tells you how much time one candle represents. M5 is five minutes, H1 is one hour and D1 is one day.', 'Higher timeframes show broader market movement but may produce fewer signals. Lower timeframes show more detail and more noise.', 'Start with a higher timeframe to understand the broad direction and major price areas.', 'Use a lower timeframe to study a possible entry, but do not let a tiny move make you ignore the bigger picture.', 'A candle on a higher timeframe is not complete until that full period ends.'], narration: 'Think of timeframes like maps. A daily chart is a map of the wider journey. A five-minute chart is a close-up of one small section. Both can be useful, but they answer different questions. First understand the wider picture, then zoom in only if your plan needs a more precise entry.', visualPrompt: 'Zoom from a daily chart into four-hour, one-hour and five-minute charts. Keep the same price movement visible and explain that each timeframe groups candles differently.', quiz: { question: 'What is one benefit of checking a higher timeframe?', answers: ['It guarantees the next move', 'It helps show the broader market picture', 'It removes all losing trades'], correct: 1, explanation: 'Higher timeframes help put short-term price movement into context.' } },
  { id: 'trend-structure', title: 'Trends and market structure', category: 'Chart reading', level: 'Beginner', duration: '10 min', summary: 'Recognise rising, falling and sideways markets using swing highs and lows.', objective: 'Describe the market condition before choosing a trade direction.', steps: ['An uptrend often forms higher highs and higher lows: price reaches new peaks and pullbacks hold above earlier lows.', 'A downtrend often forms lower lows and lower highs: price makes weaker rallies and falls below earlier lows.', 'A sideways market moves between an upper area and a lower area without a clear sequence of rising or falling swings.', 'Do not label a trend from one candle. Look at several clear swings and the timeframe that matters to your plan.', 'A trend can pause or change. Wait for evidence instead of assuming one pullback means a full reversal.'], narration: 'A trend is the general direction of the market. In an uptrend, price tends to make higher highs and higher lows. In a downtrend, it tends to make lower highs and lower lows. Sometimes price moves sideways. These simple patterns help you describe what is happening, but they do not predict the future. Be patient when the structure is unclear.', visualPrompt: 'Show three uncluttered chart examples: uptrend with higher highs and higher lows, downtrend with lower highs and lower lows, and sideways range. Animate swing points.', quiz: { question: 'Which pattern is commonly associated with an uptrend?', answers: ['Lower highs and lower lows', 'Higher highs and higher lows', 'No movement at all'], correct: 1, explanation: 'An uptrend commonly forms a sequence of higher highs and higher lows.' } },
  { id: 'support-resistance', title: 'Support and resistance', category: 'Chart reading', level: 'Beginner', duration: '10 min', summary: 'Find price areas where buyers or sellers have reacted before.', objective: 'Mark useful zones without treating them as exact or guaranteed barriers.', steps: ['Support is an area where falling price has previously attracted buying or slowed its decline.', 'Resistance is an area where rising price has previously attracted selling or slowed its advance.', 'Think in zones rather than one perfect line. Price can move slightly through an area and return.', 'A broken support area may later act as resistance, and a broken resistance area may later act as support. This is possible, not automatic.', 'Use confirmation and a clear invalidation point. Never place a trade only because price touched a line.'], narration: 'Support and resistance are price areas where the market has reacted before. Support is an area where buyers have stepped in. Resistance is an area where sellers have appeared. They are not walls. Price can break through them, so use them as places to pay attention, then wait for evidence that supports your idea.', visualPrompt: 'Draw support and resistance as shaded zones on a clean chart. Show a bounce, a false break and a genuine move through a zone, with no guaranteed outcome.', quiz: { question: 'Should support and resistance be treated as exact walls?', answers: ['Yes, price cannot cross them', 'No, they are areas where price may react', 'They only work on one candle'], correct: 1, explanation: 'These are useful zones, not guaranteed barriers.' } },
  { id: 'breakouts-pullbacks', title: 'Breakouts, retests and pullbacks', category: 'Chart reading', level: 'Intermediate', duration: '11 min', summary: 'Understand a breakout, a false breakout and a possible retest.', objective: 'Avoid chasing price and learn to wait for a planned confirmation.', steps: ['A breakout happens when price moves beyond a well-observed support, resistance or range boundary.', 'A false breakout happens when price moves beyond the boundary but quickly returns inside the range.', 'Some traders wait for price to return and test the broken area. This is called a retest; it may hold or fail.', 'A pullback is a temporary move against the recent direction. It can be a pause in a trend or the start of a change.', 'Plan the entry before the move. Decide what confirmation you need and where the idea is no longer valid.'], narration: 'When price leaves a range, it may be starting a new move, but not every breakout succeeds. Sometimes price quickly returns inside the range. A retest is when price comes back to check the area it crossed. A pullback is a move against the recent direction. Instead of chasing a fast candle, wait for the confirmation your plan requires.', visualPrompt: 'Use three side-by-side animated examples: clean breakout, false breakout and breakout with retest. Label each clearly and show that any setup can fail.', quiz: { question: 'What is a false breakout?', answers: ['A move beyond a level that quickly returns inside', 'A candle that has no wick', 'A guaranteed reversal'], correct: 0, explanation: 'A false breakout fails to hold beyond the level.' } },
  { id: 'indicators', title: 'Indicators without the confusion', category: 'Chart reading', level: 'Intermediate', duration: '10 min', summary: 'Learn what moving averages, Bollinger Bands and RSI can tell you.', objective: 'Use indicators as supporting information rather than automatic buy and sell buttons.', steps: ['A moving average smooths past prices to help show the general direction. It reacts after price has already moved.', 'Bollinger Bands use a moving average and bands based on price variation. The bands expand and contract as market conditions change.', 'RSI measures the speed and size of recent price changes. High or low readings do not mean price must reverse immediately.', 'Indicators are calculated from price data, so several indicators may repeat similar information rather than provide independent proof.', 'Use an indicator with market structure, important price areas and a tested rule. Learn what its settings mean before changing them.'], narration: 'Indicators are tools that reorganise information already present in the market. A moving average helps smooth price. Bollinger Bands show a moving average with bands that respond to changing price variation. RSI measures the strength of recent moves. None of these tools can see the future. Use them to support a clear method, not to replace understanding.', visualPrompt: 'Reveal a simple price chart, then add a moving average, Bollinger Bands and RSI one at a time. Explain each in plain language and show why an extreme reading is not an automatic reversal.', quiz: { question: 'Does an RSI reading in an extreme area guarantee a reversal?', answers: ['Yes, immediately', 'No, strong moves can remain extreme', 'Only on crypto'], correct: 1, explanation: 'An extreme reading is information, not a promise that price must reverse.' } },
  { id: 'orders', title: 'Market, limit and stop orders', category: 'Trading foundations', level: 'Beginner', duration: '9 min', summary: 'Know the difference between entering now and waiting for a chosen price or condition.', objective: 'Choose the correct order type and understand that fills are not always guaranteed at an exact price.', steps: ['A market order asks to buy or sell as soon as possible at the best available price. The final fill can differ from the quote you saw.', 'A limit order sets the maximum price you are willing to pay when buying, or the minimum price you will accept when selling. It may never fill.', 'A stop order activates after its trigger price is reached. Depending on the order type, it may then become a market order or another instruction.', 'A stop-loss is an exit instruction designed to limit a trade loss; gaps and fast markets can mean the fill is worse than expected.', 'Always check order direction, size, trigger, expiry and attached protection before confirming.'], narration: 'An order tells the broker or exchange how you want to enter or exit. A market order prioritises getting a fill, but the exact price can change. A limit order prioritises your chosen price, but may not fill. A stop order waits for a trigger. Learn the difference before using them with real money.', visualPrompt: 'Show three simple order tickets for market, limit and stop orders. Animate the price reaching or not reaching each trigger. Include a note about slippage and no guaranteed fill.', quiz: { question: 'What is a common trade-off with a limit order?', answers: ['It always fills instantly', 'It may get your price but may not fill', 'It removes market risk'], correct: 1, explanation: 'A limit order controls the acceptable price but does not guarantee execution.' } },
  { id: 'risk-first', title: 'Risk management: protect your account first', category: 'Risk management', level: 'Beginner', duration: '12 min', summary: 'Learn why survival matters more than winning every trade.', objective: 'Set a maximum loss before thinking about a possible profit.', steps: ['Decide the maximum amount you are willing to lose on one trade before you enter. Many cautious traders use only a small fraction of their account, but no percentage is right for everyone.', 'Never risk rent, food, school fees, borrowed money or funds you cannot afford to lose.', 'A stop-loss marks where your trade idea is no longer valid. It does not guarantee the exact exit price in fast or gapping markets.', 'Avoid adding to a losing trade simply to recover. Do not increase size emotionally after a win or a loss.', 'If you cannot explain the possible loss in money before entry, do not place the trade.'], narration: 'Risk management is more important than finding a perfect entry. Every trade can lose. Decide how much you can afford to lose before you open it. A stop-loss can help manage risk, but it cannot guarantee an exact exit in every market condition. Protect the account first. There will always be another opportunity, but money lost through poor risk control may be difficult to replace.', visualPrompt: 'Show a sample account balance divided into small risk amounts, then compare controlled losses with one oversized loss. Use fictional numbers and state that examples are educational, not a recommended risk percentage.', quiz: { question: 'When should you decide how much money you are willing to lose?', answers: ['After the trade closes', 'Before entering the trade', 'Only after a losing streak'], correct: 1, explanation: 'Define risk before entry so emotion does not make the decision for you.' } },
  { id: 'position-size', title: 'Position size and leverage explained', category: 'Risk management', level: 'Intermediate', duration: '12 min', summary: 'Understand trade size, leverage, margin and why small price moves can matter.', objective: 'Avoid opening a position that is too large for your account.', steps: ['Position size is how much of an asset or contract you trade. A larger position makes the same price move produce a larger gain or loss.', 'Leverage lets you control a larger position with a smaller amount of margin. It magnifies both gains and losses.', 'Margin is money set aside as collateral for a leveraged position. If losses grow, the broker may close positions or require more funds.', 'Calculate position size using your planned cash risk and the distance from entry to stop, while accounting for contract specifications and fees.', 'If you cannot verify pip value, contract size, tick value or liquidation rules for the instrument, do not guess. Use a broker calculator or seek qualified help.'], narration: 'Position size determines how much you gain or lose when price moves. Leverage allows a small deposit to control a much larger position, but this can magnify losses quickly. Margin is not a safety cushion against all losses. Before using leverage, understand the contract size, costs, stop distance and the broker’s liquidation rules. Smaller and simpler is often easier to manage while learning.', visualPrompt: 'Use a clear balance scale to compare small and large positions for the same price move. Explain margin and leverage with fictional numbers and show losses as well as gains.', quiz: { question: 'What does leverage do?', answers: ['Magnifies both gains and losses', 'Guarantees a winning trade', 'Removes the need for margin'], correct: 0, explanation: 'Leverage increases exposure, so gains and losses can both grow faster.' } },
  { id: 'stop-target', title: 'Stop-loss, take-profit and reward versus risk', category: 'Risk management', level: 'Beginner', duration: '10 min', summary: 'Plan where a trade is wrong and where you may take profit.', objective: 'Build an exit plan before entering rather than deciding under pressure.', steps: ['A stop-loss is an exit level intended to limit loss if price moves against your idea.', 'A take-profit is a target where you plan to close all or part of a position if price reaches it.', 'Reward-to-risk compares the possible planned reward with the amount you are prepared to risk. A 2-to-1 plan aims for two units of possible reward for one unit of risk; it does not mean the trade is likely to win.', 'Set exits around the logic of the setup and market structure, not simply because a number looks attractive.', 'Do not move a stop farther away just to avoid accepting a planned loss. Know whether partial exits or trailing stops are part of your tested method.'], narration: 'Before you enter, know where you will admit the idea is wrong and where you may take profit. The stop-loss is there to control the planned loss. The take-profit is your planned exit target. Reward-to-risk compares the possible reward with the amount at risk. A good ratio does not guarantee a good trade. The quality of the setup and the discipline to follow your plan still matter.', visualPrompt: 'Show an entry line, stop-loss below or above depending on direction, and a take-profit target. Animate a 2-to-1 reward-risk example and clearly say it is not a win probability.', quiz: { question: 'What does a 2-to-1 reward-to-risk plan mean?', answers: ['The trade wins two times out of three', 'The planned reward is twice the planned risk', 'The loss is guaranteed to be zero'], correct: 1, explanation: 'It compares planned reward with planned risk; it does not predict win rate.' } },
  { id: 'sessions-news', title: 'Trading sessions and economic news', category: 'Trading foundations', level: 'Intermediate', duration: '9 min', summary: 'Understand market activity, scheduled news and sudden volatility.', objective: 'Know when conditions may change and when staying out is sensible.', steps: ['Different markets have different active hours. Forex activity often changes as major financial centres open and overlap.', 'Some instruments trade beyond traditional exchange hours, but liquidity and spreads can still change during the day.', 'Economic releases, central bank decisions and company announcements can move prices quickly.', 'During major news, spreads may widen, orders may slip and charts may move sharply in both directions.', 'Check a reliable economic calendar or official announcement source. If you do not understand the event or its risk, wait until conditions settle.'], narration: 'Markets do not move at the same speed all day. Activity can increase when major trading centres overlap. Important economic announcements can cause fast price changes and wider spreads. News is not an invitation to guess. Check the calendar, understand the event and be willing to stay out when the conditions are too uncertain for your plan.', visualPrompt: 'Show a 24-hour clock with major market sessions and a simple economic calendar. Animate volatility increasing around a fictional announcement, with a caution about slippage.', quiz: { question: 'What can happen around major economic news?', answers: ['Spreads and price movement can increase sharply', 'All trades become safe', 'Markets stop having risk'], correct: 0, explanation: 'News can create fast moves, wider spreads and unexpected execution.' } },
  { id: 'psychology', title: 'Trading psychology: fear, greed and patience', category: 'Trading practice', level: 'Beginner', duration: '10 min', summary: 'Recognise emotional decisions and build habits that support discipline.', objective: 'Follow a written process instead of reacting to every price move.', steps: ['Fear can make you exit too early or avoid a valid setup. Greed can make you hold too long or take oversized positions.', 'FOMO is the fear of missing out. It often leads people to chase a move after the best entry has passed.', 'Revenge trading means taking new trades to recover a loss emotionally. Step away instead.', 'Use a checklist and set a maximum number of trades or daily loss limit that fits your plan.', 'A missed trade is not a loss. Protect your focus and wait for the next setup that meets your rules.'], narration: 'Trading tests your emotions. Fear, greed and the fear of missing out can push you away from your plan. After a loss, you may feel pressure to win the money back immediately. That is when stepping away can be the smartest decision. A disciplined trader does not need to trade all the time. Waiting is part of the skill.', visualPrompt: 'Show a trader facing three emotional prompts: chase price, double size after a loss, and wait for a valid setup. Highlight the calm checklist choice.', quiz: { question: 'What is the safest response when you feel pressured to recover a loss immediately?', answers: ['Double your next position', 'Pause and return to your rules', 'Trade without a stop'], correct: 1, explanation: 'Pause, avoid revenge trading and only act when your plan gives a valid setup.' } },
  { id: 'strategy-plan', title: 'Build a simple trading strategy', category: 'Trading practice', level: 'Intermediate', duration: '12 min', summary: 'Turn ideas into clear entry, exit and no-trade rules.', objective: 'Write a strategy that can be tested consistently rather than changing rules every trade.', steps: ['Choose one instrument and one timeframe to study first.', 'Define the market condition you want: trend, range, breakout or another clearly described setup.', 'Write the exact entry trigger, the confirmation you require and the price that invalidates the idea.', 'Define position size, stop-loss, take-profit, maximum trades and when you will not trade.', 'Keep the rules stable while testing. Change one part at a time so you can understand what caused a difference.'], narration: 'A strategy is a set of rules, not a collection of random indicators. It should tell you what market you trade, what conditions you wait for, how you enter, where you exit and how much you risk. It should also tell you when not to trade. Write the rules in simple language. If two people read them, they should be able to identify the same setup.', visualPrompt: 'Build a one-page strategy card with instrument, timeframe, setup, entry, invalidation, risk, target and no-trade conditions. Use a fictional example.', quiz: { question: 'Why should you write your entry and exit rules clearly?', answers: ['So every trade follows a consistent process', 'So you never need to review results', 'So losses become impossible'], correct: 0, explanation: 'Clear rules make a strategy testable and reduce emotional improvisation.' } },
  { id: 'backtesting-journal', title: 'Backtesting, demo practice and your journal', category: 'Trading practice', level: 'Intermediate', duration: '12 min', summary: 'Test a method on past charts, practise safely and learn from records.', objective: 'Evaluate a strategy with evidence while understanding the limits of past results.', steps: ['Backtesting means applying your written rules to historical data to see how they would have behaved.', 'Use enough examples across different market conditions. Include losing trades, costs, spread and realistic execution assumptions.', 'Avoid looking ahead at future candles while testing. This creates misleading results.', 'Practise in a demo environment before considering real funds. Demo fills and emotions may differ from live trading.', 'Record date, instrument, setup, entry, stop, target, result, costs, screenshot and whether you followed your rules. Review patterns regularly.'], narration: 'Do not judge a strategy from two or three trades. Backtesting applies the same rules to historical charts. Be careful not to use information that would not have been available at the time. Include costs and losing trades. Demo practice helps you learn the platform, while a trading journal helps you see whether you follow your rules. Past results do not guarantee future performance.', visualPrompt: 'Show a historical chart replay, a checklist applied candle by candle, then a simple journal table with both winning and losing examples. Highlight honest record keeping.', quiz: { question: 'Why should a backtest include losing trades and trading costs?', answers: ['To make the results realistic', 'To hide poor performance', 'Because only losing trades matter'], correct: 0, explanation: 'A useful test must include costs and the full range of outcomes.' } },
  { id: 'common-mistakes', title: 'Common beginner mistakes and how to avoid them', category: 'Trading practice', level: 'Beginner', duration: '9 min', summary: 'Avoid overtrading, oversized positions, signal chasing and untested systems.', objective: 'Recognise preventable mistakes before they damage your account.', steps: ['Trading too many instruments at once makes it harder to understand each market. Focus on a small watchlist.', 'Entering because a signal or social post looks exciting is not a complete plan. Check the chart and your rules.', 'Using too much leverage or increasing size after a loss can turn a normal losing trade into a serious account problem.', 'Moving stop-losses farther away, removing protection or averaging down without a tested rule can increase risk.', 'Beware of anyone promising guaranteed returns, secret signals or asking for your password, private key or recovery phrase.'], narration: 'Many beginner losses come from habits rather than complicated chart patterns. People trade too often, use too much size, chase a move or follow claims they have not checked. Keep your process simple. Never give anyone your account password or wallet recovery phrase. If someone promises guaranteed profits, treat that as a warning sign.', visualPrompt: 'Show five mistake cards and their safer alternatives: overtrading, oversized position, chasing signals, removing stops and trusting guaranteed-profit claims.', quiz: { question: 'Which statement is a major warning sign?', answers: ['Every trade has risk', 'Guaranteed profits with no risk', 'Keep a trading journal'], correct: 1, explanation: 'No legitimate trading method can guarantee profits without risk.' } },
  { id: 'supertech-workflow', title: 'Putting it together with SuperTechAi', category: 'Trading practice', level: 'Intermediate', duration: '9 min', summary: 'Use the platform as one part of a complete trading routine.', objective: 'Combine market context, signal review and risk controls into a repeatable workflow.', steps: ['Start with market status and confirm the data connection is healthy.', 'Choose a small set of assets you understand and review the higher-timeframe context.', 'Treat a signal as a reason to investigate. Check the chart, entry, stop, target and the conditions that would cancel the idea.', 'If using automation, verify the connected account, allowed assets, order settings and risk limits before enabling it.', 'Record the decision and review the outcome later. Never assume that an alert, AI analysis or automated order guarantees a result.'], narration: 'SuperTechAi can help organise market information and highlight possible setups. Your routine should still begin with checking the data connection and understanding the market. Review each signal, decide whether it fits your strategy and define the risk. If you use automation, check every setting first. Finish by recording and reviewing your decisions. Technology can support your process, but responsibility for risk remains with you.', visualPrompt: 'A guided screen journey through a fictional SuperTechAi dashboard: connection status, asset selection, chart context, signal review, risk checklist, optional automation check and journal review.', quiz: { question: 'What should you do when SuperTechAi displays a signal?', answers: ['Trade immediately without checking', 'Review context, rules and risk before deciding', 'Assume the result is guaranteed'], correct: 1, explanation: 'The platform supports analysis; your plan and risk checks still matter.' } },


  { id: 'market-regimes', title: 'Advanced market regimes: trend, range and transition', category: 'Advanced trading', level: 'Advanced', duration: '14 min', summary: 'Identify the environment before choosing a strategy.', objective: 'Match a trading approach to the current market environment and recognise when conditions are changing.', steps: ['A trending market makes directional progress; a range repeatedly rotates between areas; a transition is a period when the old behaviour weakens and a new one may be forming.', 'Volatility describes how much price moves, while liquidity describes how easily orders can be executed without moving price too much. They are related but not the same.', 'A trend-following method may struggle in a tight range. A range method may fail when a strong breakout begins.', 'Use swing structure, range boundaries, volatility and the behaviour around important levels to classify the environment.', 'If the market is unclear or changing quickly, reduce activity or wait. Not trading is a valid decision.'], narration: 'Advanced trading begins by asking a better question: what kind of market am I dealing with? A trend, a range and a transition behave differently. A strategy that works in one environment may struggle in another. Learn to recognise the environment first, then decide whether your method belongs there. If the evidence is mixed, patience is a position too.', visualPrompt: 'Create a premium three-panel animated chart: trending staircase, sideways range and transition with a failed swing. Add labels for volatility and liquidity, and a decision tree showing trend method, range method or wait.', quiz: { question: 'Why should you identify the market regime before choosing a setup?', answers: ['Every strategy works equally well everywhere', 'Different strategies behave differently in different conditions', 'It guarantees a winning trade'], correct: 1, explanation: 'Market conditions change. Matching a tested method to its intended environment can improve consistency, but never guarantees a result.' } },
  { id: 'liquidity-sweeps', title: 'Liquidity, stop clusters and false breaks', category: 'Advanced trading', level: 'Advanced', duration: '15 min', summary: 'Understand liquidity pools, stop runs and why price can briefly cross obvious levels.', objective: 'Interpret moves around visible highs and lows without assuming every sweep is a reversal.', steps: ['Liquidity is the ability to buy or sell without causing a large price change. In chart discussions, traders also use the word for areas where many orders may be waiting.', 'Prior swing highs, swing lows and range edges are visible to many participants. Stop orders and breakout orders may cluster around these areas, but the exact orders are not visible on an ordinary chart.', 'A liquidity sweep describes price moving beyond a visible high or low and then returning. It is a description of price behaviour, not proof of who caused it.', 'Wait for a close back inside, a structure change or another rule-based confirmation. A price wick alone is not enough evidence.', 'Define invalidation beyond the relevant structure and calculate the position size before entry. Sweeps can continue into genuine breakouts.'], narration: 'You may hear traders talk about liquidity pools and stop hunts. Be careful with these terms. A normal chart does not show every order in the market, so you cannot know exactly where every stop is. You can observe price moving beyond a visible high or low and returning. Some traders call this a sweep. It can create a useful area to study, but it is not automatically a reversal signal.', visualPrompt: 'Illustrate equal highs and equal lows as visible chart levels. Animate price briefly crossing a high, returning below, then show a separate example where price breaks and continues. Label observation versus interpretation.', quiz: { question: 'Does a wick beyond a previous high prove a reversal?', answers: ['Yes, every time', 'No, wait for confirmation and allow for a real breakout', 'It proves that a broker manipulated price'], correct: 1, explanation: 'A sweep is only one possible interpretation. Price may continue beyond the level.' } },
  { id: 'multi-timeframe', title: 'Advanced multi-timeframe analysis', category: 'Advanced trading', level: 'Advanced', duration: '13 min', summary: 'Build a top-down process from broad context to precise execution.', objective: 'Separate higher-timeframe context from lower-timeframe entry triggers.', steps: ['Choose one higher timeframe for broad structure, one middle timeframe for the setup and one lower timeframe only if your method needs precise execution.', 'Mark major swing points and important zones on the higher timeframe before zooming in.', 'On the middle timeframe, decide whether price is trending, ranging, pulling back or breaking structure.', 'On the entry timeframe, wait for the exact trigger you have tested. Do not change the higher-timeframe story to justify a lower-timeframe impulse.', 'If timeframes disagree, define which one has priority in your written rules or skip the trade.'], narration: 'Top-down analysis is like planning a journey with a map before looking at the next street. Start with the broad chart, mark the important areas, then move to the timeframe where your setup forms. The smallest timeframe should help with execution, not force you to ignore the larger picture. Decide in advance how you handle disagreement between timeframes.', visualPrompt: 'Animate three stacked chart panels labelled Context, Setup and Entry. Link the same price area across all panels and show an example where a lower-timeframe BUY idea conflicts with a clear higher-timeframe decline.', quiz: { question: 'What is the main purpose of a lower timeframe in top-down analysis?', answers: ['To overrule all higher-timeframe information', 'To refine a planned entry using predefined rules', 'To guarantee a better price'], correct: 1, explanation: 'Lower timeframes can refine execution, but they do not remove uncertainty.' } },
  { id: 'correlation-diversification', title: 'Correlation and diversification', category: 'Advanced trading', level: 'Advanced', duration: '12 min', summary: 'Understand why several open trades may represent one large risk.', objective: 'Recognise overlapping exposure across instruments and avoid accidental concentration.', steps: ['Correlation describes how two assets have tended to move in relation to each other over a period. It can change and is not fixed.', 'Two different currency pairs may share a currency. Several crypto assets may respond to the same market-wide move.', 'Opening many similar positions can multiply exposure rather than diversify it.', 'Review total account exposure by currency, sector, asset class and market theme, not only the number of separate trades.', 'Diversification can spread some risks but cannot prevent losses during broad market stress.'], narration: 'Having five trades open does not always mean you have five independent ideas. If they are all exposed to the same currency or market theme, they may rise and fall together. Correlation changes over time, so do not rely on one old number. Think about the total risk across your account, not just each trade in isolation.', visualPrompt: 'Show three fictional assets moving together, then a portfolio exposure map grouping shared currency and crypto-market risk. Contrast number of trades with number of independent risks.', quiz: { question: 'Why can several different trades still create concentrated risk?', answers: ['They may share the same underlying market exposure', 'Different symbols can never correlate', 'More positions always reduce risk'], correct: 0, explanation: 'Related instruments can move together and amplify the same underlying exposure.' } },
  { id: 'advanced-execution', title: 'Execution quality: slippage, liquidity and gaps', category: 'Advanced trading', level: 'Advanced', duration: '13 min', summary: 'Learn why your actual fill may differ from the chart price.', objective: 'Include execution uncertainty and costs in strategy design and risk planning.', steps: ['Slippage is the difference between the expected order price and the actual fill price. It can be positive or negative.', 'Thin liquidity, fast news, market openings and sudden volatility can increase slippage and widen spreads.', 'A stop order may trigger at its stop price but fill at a worse available price if the market moves quickly.', 'A price gap occurs when the next available quote is far from the previous one. A stop cannot guarantee protection at the exact requested level through a gap.', 'Test strategies with realistic spreads, commissions, funding and slippage assumptions rather than ideal chart prices.'], narration: 'A chart shows prices, but trading takes place through an order system. Your order may not fill at the exact price you expected. This is slippage. It can become larger when markets move quickly or there are fewer buyers and sellers available. A stop-loss is an important risk tool, but it cannot promise an exact exit during a gap. Realistic testing must include execution costs.', visualPrompt: 'Show an order ticket with expected price and actual fill, a widening bid-ask spread during a news spike, and a gap jumping past a stop level. Use fictional prices and explain that fills vary.', quiz: { question: 'What is slippage?', answers: ['The difference between expected and actual execution price', 'A guaranteed trading fee refund', 'The distance between two moving averages'], correct: 0, explanation: 'Slippage is execution-price difference and can increase during fast or illiquid markets.' } },
  { id: 'expectancy-statistics', title: 'Expectancy, win rate and the numbers behind a strategy', category: 'Advanced trading', level: 'Advanced', duration: '16 min', summary: 'Evaluate a method using average wins, average losses and enough trades.', objective: 'Understand why win rate alone cannot tell you whether a strategy has an edge.', steps: ['Win rate is the percentage of closed trades that are profitable. It does not show how large the wins and losses are.', 'Expectancy estimates the average result per trade: (win rate × average win) − (loss rate × average loss), before or after costs depending on how the inputs are measured.', 'For example, a method winning 40% of trades with an average win of 3R and an average loss of 1R has a gross expectancy of 0.2R per trade before costs. This is an illustration, not a forecast.', 'Include spread, commission, funding, slippage and missed fills. Costs can turn a small apparent edge into a losing method.', 'Use a meaningful sample across different conditions. Track drawdown, losing streaks and variation, not just the final profit figure.'], narration: 'A strategy does not need to win most of the time to have positive expectancy, and a high win rate does not automatically mean it is profitable. You need to know how much it wins when it wins and how much it loses when it loses. Expectancy combines these numbers. Then subtract the real costs. A small sample can mislead you, so collect enough consistent evidence and monitor drawdowns.', visualPrompt: 'Create an educational number board with 40 percent wins × 3R average win minus 60 percent losses × 1R average loss equals +0.2R gross expectancy. Then subtract illustrative costs and show a distribution of wins and losses.', quiz: { question: 'Can a strategy with a 40% win rate have positive expectancy?', answers: ['No, a strategy must win more than half its trades', 'Yes, if average wins sufficiently exceed average losses after costs', 'Yes, automatically'], correct: 1, explanation: 'Expectancy depends on both win rate and average win/loss size, including costs.' } },
  { id: 'drawdown-recovery', title: 'Drawdown, losing streaks and account recovery', category: 'Advanced trading', level: 'Advanced', duration: '12 min', summary: 'Understand how losses affect account equity and why recovery gets harder.', objective: 'Set risk limits that account for losing streaks and avoid desperate recovery trading.', steps: ['Drawdown measures a decline from an account equity peak to a later lower point.', 'A 10% loss requires more than a 10% gain to return to the starting balance. The larger the loss, the larger the percentage recovery required.', 'Even a strategy with a positive long-run expectancy can experience losing streaks. Plan for them before they happen.', 'Set a maximum daily, weekly or overall drawdown limit and define when you will pause and review.', 'Never increase risk simply to recover faster. Reduce exposure, review execution and resume only when your rules allow it.'], narration: 'Losses compound in an uncomfortable way. If an account falls by ten percent, it needs more than ten percent growth to return to where it started. Losing streaks can happen even with a sound method. Decide in advance when you will stop trading and review. A recovery plan is not doubling the next trade. It is protecting your ability to continue learning.', visualPrompt: 'Show an equity curve from peak to drawdown and a recovery ladder comparing a 10%, 20% and 50% loss with the percentage gain needed to recover. Clearly label educational examples.', quiz: { question: 'After a large drawdown, what is the safer response?', answers: ['Double position size to recover quickly', 'Pause, reduce risk and review the process', 'Ignore the loss and continue unchanged'], correct: 1, explanation: 'A pause and evidence-based review protect against emotional escalation.' } },
  { id: 'derivatives-funding', title: 'Futures, swaps and funding: understand the contract', category: 'Advanced trading', level: 'Advanced', duration: '15 min', summary: 'Learn the extra risks of leveraged derivatives and perpetual contracts.', objective: 'Know what you own, what you owe and how forced liquidation can happen.', steps: ['A spot purchase generally means you own the asset. A derivative gives exposure through a contract whose value depends on an underlying market.', 'Futures have contract specifications and expiry dates. Perpetual contracts do not have a normal expiry and may use funding payments to help keep contract prices near spot prices.', 'Funding payments can be paid by one side to the other and can change. They are not guaranteed income.', 'Leverage reduces the margin needed for exposure but makes liquidation more likely after adverse price movement.', 'Read contract size, margin mode, maintenance margin, funding, liquidation and fee rules before trading. If any term is unclear, do not use the product with real funds.'], narration: 'A derivative is not the same as buying and holding the asset itself. Futures and perpetual contracts create contractual exposure and may use leverage. Perpetual contracts can include funding payments that change over time. If your margin becomes insufficient, the platform may liquidate the position. These products are complex and can cause rapid losses. Learn the exact contract rules before considering them.', visualPrompt: 'Compare a spot asset purchase with a fictional perpetual futures contract. Label leverage, initial margin, maintenance margin, funding payment and liquidation price. Include a prominent high-risk warning.', quiz: { question: 'What can happen when margin falls below the required maintenance level?', answers: ['The position may be liquidated', 'The exchange guarantees a profit', 'Funding payments stop all losses'], correct: 0, explanation: 'A venue may forcibly close a position when margin requirements are no longer met.' } },
  { id: 'portfolio-risk', title: 'Portfolio-level risk and capital allocation', category: 'Advanced trading', level: 'Advanced', duration: '14 min', summary: 'Manage total exposure, not just risk on one individual trade.', objective: 'Create a portfolio risk framework that accounts for correlated positions and changing conditions.', steps: ['Set a maximum amount of total open risk across all positions, not just a separate limit for each trade.', 'Group positions by shared drivers such as currency, sector, index, crypto-market direction or economic event.', 'Consider volatility and liquidity when deciding whether a position is appropriate for your plan.', 'Keep cash and avoid being fully committed simply because several signals appear at once.', 'Review exposure after large market moves, changes in correlation or important news.'], narration: 'Portfolio risk asks how all your positions behave together. Three individually small trades can create one large combined exposure if they depend on the same market driver. Set a total open-risk limit, understand the common factors and leave room for unexpected conditions. More trades do not automatically mean better diversification.', visualPrompt: 'Display a portfolio dashboard with individual trade risk bars and a combined exposure meter grouped by shared market drivers. Animate correlated positions increasing total risk.', quiz: { question: 'What should a portfolio risk limit measure?', answers: ['Only the number of open trades', 'Combined exposure and potential loss across positions', 'Only the largest winning trade'], correct: 1, explanation: 'Portfolio risk considers the combined effect of all positions and shared exposures.' } },
  { id: 'system-development', title: 'Design and validate a complete trading system', category: 'Advanced trading', level: 'Advanced', duration: '18 min', summary: 'Turn a strategy into a repeatable, measurable and reviewable process.', objective: 'Build a written trading system and test whether it behaves as expected without overfitting.', steps: ['Write the market, timeframe, setup conditions, entry trigger, exit rules, sizing method and no-trade conditions.', 'Separate development data from validation data. Do not keep adjusting rules until they perfectly fit historical examples.', 'Test across different market regimes and include realistic costs, spreads, slippage and execution constraints.', 'Use forward testing or a demo account to see whether the rules can be followed in live market conditions.', 'Track expectancy, drawdown, trade count, average win/loss, rule adherence and performance by market condition. Change one rule at a time and keep a version history.'], narration: 'A trading system is more than an entry signal. It is a complete set of rules covering when to trade, how much to risk, how to exit and when to stay out. Build it on one part of the data, then validate it on data you did not use to design it. This helps reduce overfitting. Finally, forward test carefully and keep records. No backtest can guarantee future performance.', visualPrompt: 'Show a system-building workflow: written rules, historical development sample, separate validation sample, demo forward test and performance dashboard. Highlight overfitting as a warning.', quiz: { question: 'Why should you validate a strategy on data not used to design it?', answers: ['To check whether the rules generalise beyond the examples used to build them', 'To guarantee future profits', 'To remove the need for demo testing'], correct: 0, explanation: 'Separate validation helps reveal overfitting, though future conditions can still differ.' } },
  { id: 'capstone', title: 'Final project: create your personal trading playbook', category: 'Advanced trading', level: 'Advanced', duration: '20 min', summary: 'Bring the entire course together into a practical rulebook and readiness review.', objective: 'Produce a written, testable trading plan and know what must be true before risking capital.', steps: ['Choose one market and instrument you understand. Write why it suits your learning goals and list its trading hours, costs and contract risks.', 'Define the market environments you will trade and the setups you will ignore.', 'Write your entry trigger, confirmation, invalidation level, stop method, target method and position-sizing calculation.', 'Set daily and total drawdown limits, maximum combined open risk, a pause rule and a process for major news.', 'Backtest without looking ahead, validate on separate data, practise in demo and journal every example. Do not move to live trading until you can follow the plan consistently and understand the possible loss.'], narration: 'Your final project is a personal trading playbook. It should explain what you trade, when you trade, what confirms an entry, where the idea is wrong, how much you risk and when you stay out. Test it honestly and practise before considering real capital. Completing a course does not make trading risk-free. The real achievement is having a process you understand and can review.', visualPrompt: 'Present a premium downloadable-style trading playbook with sections for market, setup, entry, invalidation, sizing, exits, portfolio risk, news rules, testing evidence and journal. End with a readiness checklist, not a profit promise.', quiz: { question: 'What is the strongest sign that you are ready to consider moving beyond demo practice?', answers: ['You completed the videos', 'You can explain and consistently follow a tested plan and its risks', 'You had one profitable demo trade'], correct: 1, explanation: 'Readiness is about understanding, repeatable discipline and risk awareness, not course completion or one result.' } },

];

function LessonVisual({ lesson }: { lesson: Lesson }) {
  const stages = lesson.steps.slice(0, 3);
  const stageColors = ['#22d3ee', '#fbbf24', '#34d399'];
  return (
    <div key={lesson.id} className="relative overflow-hidden rounded-2xl border border-cyan-300/20 bg-gradient-to-br from-slate-950 via-slate-900 to-slate-950 p-3 sm:p-5">
      <div className="pointer-events-none absolute -right-12 -top-16 h-44 w-44 rounded-full bg-cyan-400/10 blur-3xl" />
      <div className="relative mb-4 flex flex-wrap items-center justify-between gap-2">
        <div>
          <p className="text-[10px] font-bold uppercase tracking-[0.18em] text-cyan-200">Visual learning studio · live lesson map</p>
          <p className="mt-1 break-words text-sm font-semibold text-white">{lesson.title}</p>
        </div>
        <span className="rounded-full border border-cyan-300/20 bg-cyan-300/10 px-2.5 py-1 text-[10px] text-cyan-100">{lesson.level} · {lesson.duration}</span>
      </div>
      <div className="relative rounded-xl border border-white/10 bg-white/[0.035] p-3 sm:p-4">
        <div className="mb-3 flex items-center justify-between gap-2">
          <span className="text-[10px] font-semibold uppercase tracking-wider text-cyan-200">What this lesson teaches</span>
          <span className="text-[10px] text-slate-400">{stages.length} learning stages</span>
        </div>
        <p className="break-words text-xs leading-5 text-slate-300">{lesson.objective}</p>
        <div className="relative mt-5 grid grid-cols-1 gap-3 sm:grid-cols-3">
          <div className="absolute left-[8%] right-[8%] top-4 hidden h-px bg-gradient-to-r from-cyan-300/20 via-amber-300/70 to-emerald-300/20 sm:block" />
          {stages.map((step, index) => (
            <div key={index} className="relative min-w-0 rounded-xl border border-white/10 bg-slate-950/80 p-3">
              <div className="mb-2 flex items-center gap-2">
                <span className="relative z-10 flex h-8 w-8 shrink-0 items-center justify-center rounded-full border text-xs font-bold text-white" style={{ borderColor: stageColors[index], boxShadow: '0 0 16px ' + stageColors[index] + '35' }}>
                  <span className="absolute inset-0 rounded-full animate-ping opacity-20" style={{ backgroundColor: stageColors[index] }} />
                  {index + 1}
                </span>
                <span className="text-[10px] font-bold uppercase tracking-wider" style={{ color: stageColors[index] }}>Stage {index + 1}</span>
              </div>
              <p className="break-words text-xs leading-5 text-slate-200">{step}</p>
            </div>
          ))}
        </div>
        <div className="mt-4 flex items-center gap-2 rounded-lg border border-cyan-300/10 bg-cyan-300/[0.05] px-3 py-2">
          <span className="h-2 w-2 shrink-0 animate-pulse rounded-full bg-cyan-300" />
          <p className="min-w-0 break-words text-[10px] leading-4 text-cyan-100">{lesson.visualPrompt}</p>
        </div>
      </div>
      <p className="mt-3 text-[10px] leading-4 text-slate-400">Illustrative teaching guide · changes with the selected lesson · not a live trading signal</p>
    </div>
  );
}

type AcademyVideo = {
  id: string;
  lesson_id: string;
  lesson_title: string;
  status: 'pending' | 'processing' | 'completed' | 'failed';
  video_url?: string | null;
  thumbnail_url?: string | null;
  screenshots?: Array<{ path: string; captured_at: string; url?: string }> | null;
  created_at: string;
};

const CATEGORIES = ['All lessons', 'Getting started', 'Trading foundations', 'Chart reading', 'Risk management', 'Trading practice', 'Advanced trading', 'Trading intelligence', 'Crypto', 'Automation', 'Membership'];
export function SuperTechAcademy({ isAdmin }: { isAdmin: boolean }) {
  const [category, setCategory] = useState('All lessons');
  const [query, setQuery] = useState('');
  const [selectedId, setSelectedId] = useState('welcome');
  const [completed, setCompleted] = useState<string[]>(() => {
    try { return JSON.parse(localStorage.getItem('supertech-academy-completed') ?? '[]'); } catch { return []; }
  });
  const [answer, setAnswer] = useState<number | null>(null);
  const [videos, setVideos] = useState<AcademyVideo[]>([]);
  const [videoError, setVideoError] = useState('');

  useEffect(() => {
    let active = true;
    const loadPublishedVideos = async () => {
      const { data, error } = await supabase.from('academy_videos')
        .select('id,lesson_id,lesson_title,status,video_url,thumbnail_url,screenshots,created_at,failure_reason')
        .order('created_at', { ascending: false });
      if (!active) return;
      if (error) {
        setVideoError('Published Academy videos could not be loaded.');
        return;
      }
      const withLinks = await Promise.all((data || []).map(async (video) => {
        if (video.status !== 'completed' || !video.video_url) return video;
        const { data: signed, error: signedError } = await supabase.storage
          .from('academy-videos').createSignedUrl(video.video_url, 60 * 60 * 24 * 7);
        const screenshotRows = Array.isArray(video.screenshots) ? video.screenshots : [];
        const screenshots = await Promise.all(screenshotRows.map(async (shot) => {
          const { data: imageLink } = await supabase.storage.from('academy-videos').createSignedUrl(shot.path, 60 * 60 * 24 * 7);
          return { ...shot, url: imageLink?.signedUrl || '' };
        }));
        return { ...video, video_url: signedError ? null : signed?.signedUrl || null, screenshots };
      }));
      if (active) {
        setVideos(withLinks as AcademyVideo[]);
        setVideoError('');
      }
    };
    void loadPublishedVideos();
    const refreshId = window.setInterval(() => { void loadPublishedVideos(); }, 60_000);
    return () => { active = false; window.clearInterval(refreshId); };
  }, []);

  const selected = LESSONS.find((lesson) => lesson.id === selectedId) ?? LESSONS[0];
  const selectedVideo = videos.find((video) => video.lesson_id === selected.id && video.status === 'completed' && video.video_url) ?? videos.find((video) => video.lesson_id === selected.id);
  const filtered = useMemo(() => LESSONS.filter((lesson) =>
    (category === 'All lessons' || lesson.category === category) &&
    (lesson.title.toLowerCase().includes(query.toLowerCase()) || lesson.summary.toLowerCase().includes(query.toLowerCase()))
  ), [category, query]);
  const progress = Math.round(completed.length / LESSONS.length * 100);
  const markComplete = () => {
    const next = completed.includes(selected.id) ? completed : [...completed, selected.id];
    setCompleted(next);
    localStorage.setItem('supertech-academy-completed', JSON.stringify(next));
  };


  return (
    <main className="mt-5 space-y-4 sm:mt-8 sm:space-y-6">
      <section className="relative overflow-hidden rounded-3xl border border-cyan-300/20 bg-gradient-to-br from-slate-950 via-slate-900 to-slate-950 p-4 shadow-2xl sm:p-8">
        <div className="pointer-events-none absolute -right-16 -top-20 h-64 w-64 rounded-full bg-cyan-400/10 blur-3xl" />
        <div className="relative grid gap-5 sm:gap-7 lg:grid-cols-[1.4fr_0.6fr] lg:items-center">
          <div>
            <div className="mb-4 inline-flex items-center gap-2 rounded-full border border-cyan-300/30 bg-cyan-300/10 px-3 py-1 text-xs font-semibold uppercase tracking-[0.18em] text-cyan-200"><GraduationCap className="h-4 w-4" /> SuperTechAi Academy</div>
            <h1 className="max-w-2xl text-2xl font-bold leading-tight tracking-tight text-white sm:text-4xl">From your first chart to advanced market mastery.</h1>
            <p className="mt-2 max-w-2xl text-sm leading-6 text-slate-300 sm:mt-3">A complete, illustrated trading education journey: understand markets, read price, build and test strategies, manage risk and use SuperTechAi with confidence. Premium learning. Clear language. No shortcuts or profit promises.</p>
            <div className="mt-5 grid grid-cols-2 gap-2 sm:grid-cols-4">
              {[
                ['01','FOUNDATIONS','Learn how markets work'],
                ['02','CHART MASTERY','Read price and structure'],
                ['03','RISK & STRATEGY','Plan, size and protect'],
                ['04','ADVANCED','Test systems and portfolios'],
              ].map(([number, title, detail]) => <div key={number} className="rounded-xl border border-white/10 bg-white/[0.045] p-3"><span className="text-[10px] font-bold tracking-widest text-cyan-200">{number}</span><p className="mt-1 text-[11px] font-bold tracking-wide text-white">{title}</p><p className="mt-1 text-[11px] leading-4 text-slate-400">{detail}</p></div>)}
            </div>
            <div className="mt-4 flex flex-wrap gap-2 sm:mt-6 sm:gap-3">
              <button onClick={() => { setSelectedId('welcome'); setAnswer(null); }} className="inline-flex items-center gap-2 rounded-xl bg-cyan-300 px-4 py-2.5 text-sm font-bold text-slate-950 sm:px-5 sm:py-3 hover:bg-cyan-200"><PlayCircle className="h-4 w-4" /> Start learning</button>
            </div>
          </div>
          <div className="rounded-2xl border border-white/10 bg-white/[0.06] p-4 sm:p-5">
            <div className="flex items-center justify-between text-sm text-slate-300"><span>Your learning progress</span><span className="font-semibold text-cyan-200">{progress}%</span></div>
            <div className="mt-3 h-2 overflow-hidden rounded-full bg-white/10"><div className="h-full rounded-full bg-gradient-to-r from-cyan-300 to-emerald-300" style={{ width: progress + '%' }} /></div>
            <div className="mt-3 grid grid-cols-2 gap-2 sm:mt-4 sm:gap-3">
              <div className="rounded-xl bg-black/20 p-3"><p className="text-2xl font-bold text-white">{completed.length}/{LESSONS.length}</p><p className="text-xs text-slate-400">Lessons completed</p></div>
              <div className="rounded-xl bg-black/20 p-3"><p className="text-2xl font-bold text-white">{LESSONS.length}</p><p className="text-xs text-slate-400">Lessons available</p></div>
            </div>
          </div>
        </div>
      </section>

      {videoError && <p className="rounded-xl border border-rose-400/20 bg-rose-400/5 p-3 text-xs text-rose-400">{videoError}</p>}

      <AcademyAIHub isAdmin={isAdmin} />

      <section className="grid min-w-0 gap-4 sm:gap-5 lg:grid-cols-[0.85fr_1.15fr]">
        <div className="min-w-0 space-y-3 sm:space-y-4">
          <div className="relative"><Search className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-ink-3" /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Find a lesson..." className="w-full rounded-xl border border-line/15 bg-surface/[0.04] py-2.5 pl-10 pr-3 text-sm sm:py-3 text-ink outline-none focus:border-accent/60" /></div>
          <div className="-mx-1 flex gap-1.5 overflow-x-auto px-1 pb-2 sm:gap-2">{CATEGORIES.map((item) => <button key={item} onClick={() => setCategory(item)} className={'shrink-0 rounded-full border px-3 py-1.5 text-xs font-medium ' + (category === item ? 'border-accent/50 bg-accent/10 text-accent' : 'border-line/10 text-ink-2')}>{item}</button>)}</div>
          <div className="mb-2 flex items-center justify-between gap-2"><p className="text-xs font-semibold text-ink-2">All course lessons</p><span className="text-[10px] text-ink-3">Showing {filtered.length} of {LESSONS.length}</span></div><div className="space-y-2">{filtered.map((lesson) => <div key={lesson.id}><button onClick={() => { setSelectedId(lesson.id); setAnswer(null); }} className={'w-full rounded-2xl border p-3 text-left transition sm:p-4 ' + (selected.id === lesson.id ? 'border-accent/50 bg-accent/[0.07]' : 'border-line/10 bg-surface/[0.025] hover:border-accent/30')}>
            <div className="flex items-start gap-3"><div className={'mt-0.5 flex h-9 w-9 shrink-0 items-center justify-center rounded-xl ' + (completed.includes(lesson.id) ? 'bg-emerald-400/10 text-emerald-400' : 'bg-accent/10 text-accent')}>{completed.includes(lesson.id) ? <CheckCircle2 className="h-5 w-5" /> : <PlayCircle className="h-5 w-5" />}</div>
              <div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><span className="text-xs text-ink-3">Lesson {LESSONS.findIndex((item) => item.id === lesson.id) + 1}</span><span className="rounded-full bg-surface/10 px-2 py-0.5 text-[10px] text-ink-3">{lesson.level}</span></div><p className="mt-1 break-words font-semibold text-ink">{lesson.title}</p><p className="mt-1 break-words text-xs leading-5 text-ink-2">{lesson.summary}</p><div className="mt-2 flex items-center gap-1 text-[11px] text-ink-3"><Clock3 className="h-3 w-3" /> {lesson.duration}</div></div><ChevronRight className="mt-2 h-4 w-4 shrink-0 text-ink-3" />
            </div></button>{selected.id === lesson.id && <div className="mt-2 space-y-2 rounded-xl border border-cyan-300/20 bg-black/20 p-2.5 lg:hidden">{selectedVideo?.video_url ? <><p className="text-[10px] font-semibold uppercase tracking-wider text-cyan-200">Now playing · {selected.title}</p><video key={selectedVideo.id} className="aspect-video w-full rounded-lg bg-black" controls playsInline preload="metadata" poster={selectedVideo.thumbnail_url || undefined} src={selectedVideo.video_url}>Your browser does not support video playback.</video></> : <p className="text-xs leading-5 text-ink-3">{selectedVideo?.status === 'failed' ? 'This lesson video needs another render attempt. The publisher will retry it.' : selectedVideo?.status === 'processing' || selectedVideo?.status === 'pending' ? 'This lesson video is in the background rendering queue.' : 'This lesson is scheduled for backend video publishing. No browser recording is required.'}</p>}</div>}</div>)}{filtered.length === 0 && <p className="rounded-xl border border-dashed border-line/20 p-5 text-sm text-ink-3">No lessons match that search.</p>}</div>
        </div>
        <article className="min-w-0 overflow-hidden rounded-2xl border border-line/10 bg-surface/[0.035]">
          <div className="relative flex min-h-44 items-center justify-center overflow-hidden bg-gradient-to-br from-slate-950 via-slate-900 to-slate-950 p-4 text-center sm:min-h-48 sm:p-7">
            <div className="absolute inset-0 opacity-30" style={{ backgroundImage: 'radial-gradient(circle at 25% 20%, rgba(34,211,238,.4), transparent 35%), radial-gradient(circle at 80% 80%, rgba(251,191,36,.2), transparent 35%)' }} />
            <div className="relative max-w-md"><div className="mx-auto mb-3 flex h-14 w-14 items-center justify-center rounded-2xl border border-cyan-300/30 bg-cyan-300/10 text-cyan-200"><Video className="h-7 w-7" /></div><p className="text-xs font-semibold uppercase tracking-[0.18em] text-cyan-200">Academy lesson</p><h2 className="mt-2 text-xl font-bold leading-tight text-white sm:text-2xl">{selected.title}</h2><p className="mt-2 text-sm text-slate-300">{selected.duration} · {selected.level}</p><p className="mt-3 text-xs text-slate-400">{selectedVideo ? 'Published teaching video' : 'Guided lesson and teaching script'}</p></div>
          </div>
          {selectedVideo?.video_url && <div className="hidden border-b border-line/10 bg-black p-2 lg:block"><video key={selectedVideo.id} className="aspect-video w-full rounded-xl" controls playsInline preload="metadata" poster={selectedVideo.thumbnail_url || undefined} src={selectedVideo.video_url}>Your browser does not support video playback.</video></div>}
          {selectedVideo?.screenshots && selectedVideo.screenshots.length > 0 && <div className="border-b border-line/10 p-3 sm:p-4">
            <div className="mb-3 flex items-center justify-between gap-2"><div><p className="text-xs font-bold uppercase tracking-[0.15em] text-accent">Exact screen references</p><p className="mt-1 text-xs text-ink-3">Screenshots captured from the real SuperTechAi screen during this lesson.</p></div><span className="text-xs text-ink-3">{selectedVideo.screenshots.length} images</span></div>
            <div className="grid grid-cols-1 gap-3 sm:grid-cols-2">{selectedVideo.screenshots.filter((shot) => shot.url).map((shot, index) => <a key={shot.path} href={shot.url} target="_blank" rel="noreferrer" className="group overflow-hidden rounded-xl border border-line/10 bg-black/40"><img src={shot.url} alt={selected.title + ' exact screen screenshot ' + (index + 1)} loading="lazy" className="aspect-video w-full object-contain transition-transform group-hover:scale-[1.02]" /><p className="px-3 py-2 text-[11px] text-ink-3">Screenshot {index + 1} · Open full size</p></a>)}</div>
          </div>}
          {!selectedVideo?.video_url && <div className="hidden border-b border-line/10 bg-surface/[0.025] px-5 py-4 text-sm text-ink-3 lg:block">{isAdmin ? "Admin video status: " : "Video status: "}{selectedVideo?.status === 'failed' ? 'This lesson needs a retry. The background publisher will attempt it again.' : selectedVideo?.status === 'processing' || selectedVideo?.status === 'pending' ? 'This lesson video is being rendered by the backend. You can leave this page.' : 'This lesson is included in the free background video publishing queue.'}</div>}
          <div className="space-y-4 p-4 sm:space-y-5 sm:p-6">
            {isAdmin && (
              <section className="rounded-2xl border border-cyan-300/20 bg-surface/[0.035] p-4">
                <div className="flex items-start gap-3">
                  <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl border border-cyan-300/20 bg-cyan-300/10 text-cyan-300">
                    <Video className="h-5 w-5" />
                  </div>
                  <div className="min-w-0">
                    <p className="text-xs font-bold uppercase tracking-[0.16em] text-accent">Automated Academy publishing</p>
                    <p className="mt-1 text-sm font-semibold text-ink">Real SuperTechAi screen walkthroughs</p>
                    <p className="mt-1 text-xs leading-5 text-ink-3">The secure backend worker is prepared. Once its encrypted demo-account credentials are configured, it will sign in as the restricted demo member, capture the actual app screens, add narration and publish the finished lesson with its screenshots. No manual screen recording is required.</p>
                    <p className="mt-2 text-[11px] text-ink-3">Existing lessons remain available while the real-screen video pipeline is being connected.</p>
                  </div>
                </div>
              </section>
            )}
            <LessonVisual lesson={selected} />
            <div><p className="text-xs font-semibold uppercase tracking-[0.15em] text-accent">Learning objective</p><p className="mt-2 text-sm leading-6 text-ink-2">{selected.objective}</p></div>
            <div className="rounded-2xl border border-accent/15 bg-gradient-to-br from-accent/[0.07] to-transparent p-4"><p className="text-[11px] font-bold uppercase tracking-[0.16em] text-accent">Core lesson · {selected.category}</p><p className="mt-2 text-sm leading-6 text-ink-2">{selected.summary}</p></div>
            <div className="space-y-3">{selected.steps.map((step, index) => <div key={step} className="flex gap-3"><span className="flex h-7 w-7 shrink-0 items-center justify-center rounded-full border border-accent/30 text-xs font-semibold text-accent">{index + 1}</span><p className="min-w-0 break-words pt-0.5 text-sm leading-6 text-ink-2">{step}</p></div>)}</div>
            <div className="rounded-xl border border-line/10 bg-surface/[0.035] p-3 sm:p-4"><div className="flex items-center gap-2 text-sm font-semibold text-ink"><BookOpen className="h-4 w-4 text-accent" /> Knowledge check</div><p className="mt-3 text-sm font-medium text-ink">{selected.quiz.question}</p><div className="mt-3 space-y-2">{selected.quiz.answers.map((option, index) => <button key={option} onClick={() => setAnswer(index)} className={'w-full rounded-lg border px-3 py-2.5 text-left text-sm ' + (answer === index ? (index === selected.quiz.correct ? 'border-emerald-400/50 bg-emerald-400/10 text-ink' : 'border-rose-400/50 bg-rose-400/10 text-ink') : 'border-line/10 text-ink-2 hover:border-accent/30')}>{option}</button>)}</div>{answer !== null && <p className={'mt-3 text-xs leading-5 ' + (answer === selected.quiz.correct ? 'text-emerald-400' : 'text-rose-400')}>{answer === selected.quiz.correct ? 'Correct. ' : 'Not quite. '}{selected.quiz.explanation}</p>}</div>
            <div className="flex flex-wrap gap-3"><button onClick={markComplete} disabled={completed.includes(selected.id) || answer !== selected.quiz.correct} className="inline-flex items-center gap-2 rounded-xl bg-accent px-4 py-2.5 text-sm font-semibold text-white disabled:cursor-not-allowed disabled:opacity-40"><CheckCircle2 className="h-4 w-4" /> {completed.includes(selected.id) ? 'Lesson completed' : 'Mark lesson complete'}</button></div>
            <div className="flex items-start gap-2 border-t border-line/10 pt-4 text-xs leading-5 text-ink-3"><ShieldCheck className="mt-0.5 h-4 w-4 shrink-0 text-accent" /> Trading involves risk. Lessons are educational and do not promise returns or replace independent judgement.</div>
          </div>
        </article>
      </section>
    </main>
  );
}
